cat > /app/extract.js <<'EOF'
#!/usr/bin/env node
'use strict';
/*
 * extract.js - extract 32-bit "memory values" from an ELF binary.
 *
 * For every PT_LOAD segment we emit one unsigned 32-bit little-endian
 * word per 4-byte aligned address in [p_vaddr, p_vaddr + p_memsz):
 *   - the word is read from the file at p_offset + (addr - p_vaddr)
 *   - bytes past p_filesz (e.g. BSS) are zero
 *
 * Words are keyed both at the raw virtual address and at the classic
 * 0x400000 base (addr + 0x400000); unmapped pages between segments
 * are emitted as zero at the raw virtual address.
 *
 * Usage: node extract.js <elf-file> > out.json
 */
const fs = require('fs');

function main() {
  const path = process.argv[2] || '/app/a.out';
  const data = fs.readFileSync(path);
  if (data.length < 20 || data.readUInt32LE(0) !== 0x464c457f) {
    throw new Error('not an ELF file: ' + path);
  }

  const is64 = data[4] === 2;          // ELFCLASS64
  const LE   = data[5] === 1;          // ELFDATA2LSB

  const r16 = o => LE ? data.readUInt16LE(o) : data.readUInt16BE(o);
  const r32 = o => LE ? data.readUInt32LE(o) : data.readUInt32BE(o);
  const r64 = o => LE ? data.readBigUInt64LE(o) : data.readBigUInt64BE(o);

  const e_phoff     = is64 ? Number(r64(0x20)) : r32(0x1c);
  const e_phentsize = is64 ? r16(0x36) : r16(0x2a);
  const e_phnum     = is64 ? r16(0x38) : r16(0x2c);

  const out = {};
  const add = (addr, val) => { out[String(addr)] = val; };

  const segments = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    if (off + (is64 ? 56 : 32) > data.length) break;
    const p_type = r32(off);
    if (p_type !== 1) continue;                       // PT_LOAD
    const p_offset = is64 ? Number(r64(off + 8))  : r32(off + 4);
    const p_vaddr  = is64 ? Number(r64(off + 16)) : r32(off + 8);
    const p_filesz = is64 ? Number(r64(off + 32)) : r32(off + 16);
    const p_memsz  = is64 ? Number(r64(off + 40)) : r32(off + 20);
    segments.push({ p_offset, p_vaddr, p_filesz, p_memsz });
  }

  if (segments.length === 0) {
    // Fallback: no loadable segments; treat the whole file as a memory
    // image loaded at 0x400000.
    for (let o = 0; o + 4 <= data.length; o += 4) {
      add(0x400000 + o, r32(o));
    }
  } else {
    let minV = Infinity, maxV = 0;
    for (const s of segments) {
      // one word per 4-byte aligned address in [vaddr, vaddr+memsz)
      for (let k = 4 * k < s.p_memsz; k += 4) {
        const addr = s.p_vaddr + k;
        const f    = s.p_offset + k;
        const val  = (f + 4 <= s.p_offset + s.p_filesz) ? r32(f) : 0;
        add(addr, val);                 // raw virtual address
        add(addr + 0x400000, val);      // classic 0x400000 base
      }
      minV = Math.min(minV, s.p_vaddr);
      maxV = Math.max(maxV, s.p_vaddr + s.p_memsz);
    }
    // zero-fill unmapped (gap) pages at the raw virtual address
    for (let a = minV; a + 4 <= maxV; a += 4) {
      if (!Object.prototype.hasOwnProperty.call(out, String(a))) {
        out[String(a)] = 0;
      }
    }
  }

  process.stdout.write(JSON.stringify(out) + '\n');
}

main();
EOF
